-- Queues: call queues managed by the admin UI.
--
-- Asterisk reads these from queues.conf (regenerated by the backend).
-- Fields match app_queue's per-queue options. `acw_seconds` is NOT read
-- by Asterisk — it's used by the agent panel (Phase 7) to enforce
-- after-call work time. Storing it here keeps the schema stable.

CREATE TABLE queues (
    id                UUID PRIMARY KEY,
    number            TEXT UNIQUE NOT NULL,
    name              TEXT NOT NULL,
    strategy          TEXT NOT NULL DEFAULT 'ringall',
    timeout           INTEGER NOT NULL DEFAULT 15,
    retry             INTEGER NOT NULL DEFAULT 5,
    maxlen            INTEGER NOT NULL DEFAULT 10,
    acw_seconds       INTEGER NOT NULL DEFAULT 15,
    musicclass        TEXT NOT NULL DEFAULT 'default',
    joinempty         BOOLEAN NOT NULL DEFAULT true,
    leavewhenempty    BOOLEAN NOT NULL DEFAULT false,
    ringinuse         BOOLEAN NOT NULL DEFAULT false,
    active            BOOLEAN NOT NULL DEFAULT true,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_queues_number ON queues (number);
CREATE INDEX idx_queues_active ON queues (active);

-- Members: many-to-many between queues and extensions.
CREATE TABLE queue_members (
    queue_id     UUID NOT NULL REFERENCES queues(id) ON DELETE CASCADE,
    extension_id UUID NOT NULL REFERENCES extensions(id) ON DELETE CASCADE,
    penalty      INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (queue_id, extension_id)
);

CREATE INDEX idx_queue_members_queue ON queue_members (queue_id);
CREATE INDEX idx_queue_members_extension ON queue_members (extension_id);
